<DIV style="position:relative; left:0px; top:0px; width:980px; height:2728px;">

<script type="text/javascript">

	// ---------------------------------------------------------
	// 表題と受理欄の入力制御
	// ---------------------------------------------------------
	function ctlChk_monthCertificate(f){
		if (f.wage_monthly_certificate_on_leave_start.checked){
			f.wage_monthly_certificate_on_leave_start_acceptance.checked = true;
		} else {
			f.wage_monthly_certificate_on_leave_start_acceptance.checked = false;
		}
	}
	
	function ctlChk_wagesCertificate(f){
		if (f.wage_certificate_working_hours_shortened_start.checked){
			f.wage_certificate_working_hours_shortened_start_acceptance.checked = true;
		} else {
			f.wage_certificate_working_hours_shortened_start_acceptance.checked = false;
		}
	}

    function katakanaCheck(f){
        var st = f.value;
        var zenkaku = "０１２３４５６７８９＋‐－ー＃￥＆．，：＊　";
        zenkaku += "ァアィイゥウェエォオカガキギクグケゲコゴサザシジスズセゼソゾタダチヂッツヅテデトド";
        zenkaku += "ナニヌネノハバパヒビピフブプヘベペホボポマミムメモャヤュユョヨラリルレロヮワヰヱヲンヴヵヶ";
        zenkaku += "ＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ";
        var reg = new RegExp("[^" + zenkaku + "]","g");
        if (st.match(reg) != null){
            alert("指定可能な文字以外が指定されています。\n\n【指定可能な文字】\n全角カナ、全角英数字\n全角記号（＋‐－ー＃￥＆．，：＊）、全角空白");
            f.focus();
        }
    }

	function calc1 (f) {
		var nullFlg = true;

		val = (f.wage_amount_a1.value - 0) + (f.wage_amount_b1.value - 0) ;

		if(f.wage_amount_a1.value == "" && f.wage_amount_b1.value == ""){
			nullFlg = false; 
		}

		if (isNaN(val) == false && nullFlg == true) {
			f.total_wages1.value = val;
		}else{
			f.total_wages1.value = "";
		}
		
		return false;
	}

	function calc2 (f, line) {
		var nullFlg = true;

		var total = (f.elements["wage_amount_a1_" + line].value - 0) + (f.elements["wage_amount_b1_" + line].value - 0);

		if((f.elements["wage_amount_a1_" + line].value) == "" && (f.elements["wage_amount_b1_" + line].value) == ""){
			nullFlg = false; 
		}

		if (isNaN(total) == false && nullFlg == true) {
			f.elements["total_wages1_" + line].value = total;
		}else{
			f.elements["total_wages1_" + line].value = "";
		}
		
		return false;
	}

	function calc4 (f, line) {
		var nullFlg = true;

		var total = (f.elements["wage_amount_a2_" + line].value - 0) + (f.elements["wage_amount_b2_" + line].value - 0);

		if((f.elements["wage_amount_a2_" + line].value) == "" && (f.elements["wage_amount_b2_" + line].value) == ""){
			nullFlg = false; 
		}

		if (isNaN(total) == false && nullFlg == true) {
			f.elements["total_wages2_" + line].value = total;
		}else{
			f.elements["total_wages2_" + line].value = "";
		}
		
		return false;
	}

	function zokushiCheck1(f){

		var chk_cnt = 0;
		var iArray = new Array("applicable_period_start_month2_1","applicable_period_start_day2_1","applicable_period_end_month2_1","applicable_period_end_day2_1");

		for (i=0; i<iArray.length; i++) {
			if ("" != f.elements[iArray[i]].value) {
				chk_cnt++;
			}
		}

		if (0 < chk_cnt) {
			f.J111_check_flg.value = "1";
		} else {
			f.J111_check_flg.value = "";
		}
	}

	function zokushiCheck2(f){

		var chk_cnt = 0;
		var trimStr;
		var iArray = new Array("applicable_period_start_month2_","applicable_period_start_day2_","applicable_period_end_month2_","applicable_period_end_day2_","basic_days2_"
								,"payment_period_start_month2_","payment_period_start_day2_","payment_period_end_month2_","payment_period_end_day2_","payment_period_basic_days2_"
								,"wage_amount_a2_","wage_amount_b2_","total_wages2_","note2_");

		for (i=0; i<iArray.length; i++) {
			for (j=2; j<=15; j++) {
				// 全角スペース、半角スペース、改行、タブのみの場合は入力なしとみなす
				trimStr = f.elements[iArray[i]+j].value.replace(/\s|　/g,"");
				if ("" != trimStr) {
					chk_cnt++;
				}
			}
		}

		if (0 < chk_cnt) {
			f.J112_check_flg2.value = "1";
		} else {
			f.J112_check_flg2.value = "";
		}
	}

</script>

